create table if not exists public.crm_experiments (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, status text not null default 'draft' check(status in ('draft','running','paused','completed')), objective text not null default 'conversion', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.crm_experiment_variants (id uuid primary key default gen_random_uuid(), experiment_id uuid not null references public.crm_experiments(id) on delete cascade, name text not null, weight numeric(8,4) not null default 1 check(weight>0), config jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), unique(experiment_id,name));
create table if not exists public.crm_experiment_exposures (id uuid primary key default gen_random_uuid(), experiment_id uuid not null references public.crm_experiments(id) on delete cascade, variant_id uuid not null references public.crm_experiment_variants(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, subject_key text not null, conversation_id uuid, exposed_at timestamptz not null default now(), unique(experiment_id,subject_key));
create table if not exists public.crm_experiment_outcomes (id uuid primary key default gen_random_uuid(), experiment_id uuid not null references public.crm_experiments(id) on delete cascade, variant_id uuid not null references public.crm_experiment_variants(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, subject_key text not null, outcome text not null, value numeric, occurred_at timestamptz not null default now());
create index if not exists crm_exp_user_status_idx on public.crm_experiments(user_id,status);
create index if not exists crm_exp_exposure_subject_idx on public.crm_experiment_exposures(user_id,subject_key);
create index if not exists crm_exp_outcome_idx on public.crm_experiment_outcomes(experiment_id,variant_id,outcome);
alter table public.crm_experiments enable row level security; alter table public.crm_experiment_variants enable row level security; alter table public.crm_experiment_exposures enable row level security; alter table public.crm_experiment_outcomes enable row level security;
drop policy if exists crm_experiments_owner on public.crm_experiments; create policy crm_experiments_owner on public.crm_experiments for all using(user_id=auth.uid()) with check(user_id=auth.uid());
drop policy if exists crm_exp_variants_owner on public.crm_experiment_variants; create policy crm_exp_variants_owner on public.crm_experiment_variants for all using(experiment_id in(select id from public.crm_experiments where user_id=auth.uid())) with check(experiment_id in(select id from public.crm_experiments where user_id=auth.uid()));
drop policy if exists crm_exp_exposures_owner on public.crm_experiment_exposures; create policy crm_exp_exposures_owner on public.crm_experiment_exposures for all using(user_id=auth.uid()) with check(user_id=auth.uid());
drop policy if exists crm_exp_outcomes_owner on public.crm_experiment_outcomes; create policy crm_exp_outcomes_owner on public.crm_experiment_outcomes for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create or replace function public.crm_experiment_assign(p_experiment_id uuid,p_subject_key text,p_conversation_id uuid default null) returns jsonb language plpgsql security invoker set search_path=public as $$ declare v_user uuid:=auth.uid(); v_exp record; v_variant record; v_hash int; v_total numeric:=0; v_cursor numeric:=0; v_pick numeric; begin if v_user is null then raise exception 'UNAUTHORIZED'; end if; select * into v_exp from public.crm_experiments where id=p_experiment_id and user_id=v_user and status='running' for update; if not found then raise exception 'EXPERIMENT_NOT_RUNNING'; end if; if exists(select 1 from public.crm_experiment_exposures where experiment_id=p_experiment_id and subject_key=p_subject_key) then select v.id,v.name,v.config into v_variant from public.crm_experiment_variants v join public.crm_experiment_exposures e on e.variant_id=v.id where e.experiment_id=p_experiment_id and e.subject_key=p_subject_key; return jsonb_build_object('experiment_id',p_experiment_id,'variant_id',v_variant.id,'variant',v_variant.name,'config',v_variant.config,'reused',true); end if; select coalesce(sum(weight),0) into v_total from public.crm_experiment_variants where experiment_id=p_experiment_id; if v_total<=0 then raise exception 'NO_VARIANTS'; end if; v_hash:=('x'||substr(md5(p_experiment_id::text||':'||p_subject_key),1,8))::bit(32)::int & 2147483647; v_pick:=mod(v_hash::numeric,1000000)/1000000*v_total; for v_variant in select * from public.crm_experiment_variants where experiment_id=p_experiment_id order by id loop v_cursor:=v_cursor+v_variant.weight; if v_pick<v_cursor then insert into public.crm_experiment_exposures(experiment_id,variant_id,user_id,subject_key,conversation_id) values(p_experiment_id,v_variant.id,v_user,p_subject_key,p_conversation_id) on conflict do nothing; return jsonb_build_object('experiment_id',p_experiment_id,'variant_id',v_variant.id,'variant',v_variant.name,'config',v_variant.config,'reused',false); end if; end loop; raise exception 'ASSIGNMENT_FAILED'; end; $$;
create or replace function public.crm_experiment_record_outcome(p_exposure_id uuid,p_outcome text,p_value numeric default null) returns uuid language plpgsql security invoker set search_path=public as $$ declare e record; oid uuid; begin select * into e from public.crm_experiment_exposures where id=p_exposure_id and user_id=auth.uid(); if not found then raise exception 'EXPOSURE_NOT_FOUND'; end if; insert into public.crm_experiment_outcomes(experiment_id,variant_id,user_id,subject_key,outcome,value) values(e.experiment_id,e.variant_id,e.user_id,e.subject_key,p_outcome,p_value) returning id into oid; return oid; end; $$;
revoke all on function public.crm_experiment_assign(uuid,text,uuid) from public,anon; grant execute on function public.crm_experiment_assign(uuid,text,uuid) to authenticated;
revoke all on function public.crm_experiment_record_outcome(uuid,text,numeric) from public,anon; grant execute on function public.crm_experiment_record_outcome(uuid,text,numeric) to authenticated;
